"""Tests for sequences of validators in deep validation factories."""

import pytest

from attr.validators import deep_iterable, deep_mapping


@pytest.mark.parametrize("sequence_type", [list, tuple])
@pytest.mark.parametrize(
    "argument",
    [
        "member_validator",
        "iterable_validator",
        "key_validator",
        "value_validator",
        "mapping_validator",
    ],
)
@pytest.mark.parametrize("failure_index", [None, 0, 1])
def test_validator_sequences(sequence_type, argument, failure_index):
    """Apply validators in order and stop at the first failure."""
    calls = []
    instance = object()
    attribute = object()

    def first(inst, attr, value):
        calls.append((0, inst, attr, value))
        if failure_index == 0:
            raise ValueError("first failed")

    def second(inst, attr, value):
        calls.append((1, inst, attr, value))
        if failure_index == 1:
            raise ValueError("second failed")

    def accept(inst, attr, value):
        pass

    validators = sequence_type([first, second])
    if argument in ("member_validator", "iterable_validator"):
        value = [42]
        kwargs = {"member_validator": accept, argument: validators}
        validator = deep_iterable(**kwargs)
        expected_value = 42 if argument == "member_validator" else value
    else:
        value = {"key": 42}
        kwargs = {"key_validator": accept, argument: validators}
        validator = deep_mapping(**kwargs)
        expected_value = {
            "key_validator": "key",
            "value_validator": 42,
            "mapping_validator": value,
        }[argument]

    if failure_index is None:
        validator(instance, attribute, value)
    else:
        message = "first failed" if failure_index == 0 else "second failed"
        with pytest.raises(ValueError, match=message):
            validator(instance, attribute, value)

    expected_calls = [(0, instance, attribute, expected_value)]
    if failure_index != 0:
        expected_calls.append((1, instance, attribute, expected_value))
    assert expected_calls == calls


@pytest.mark.parametrize("sequence_type", [list, tuple])
def test_empty_validator_sequences(sequence_type):
    """Accept empty validator sequences as no-op validators."""
    deep_iterable(sequence_type(), sequence_type())(None, None, [42])
    deep_mapping(
        key_validator=sequence_type(),
        mapping_validator=sequence_type(),
    )(None, None, {"key": 42})
    deep_mapping(value_validator=sequence_type())(None, None, {"key": 42})


@pytest.mark.parametrize("sequence_type", [list, tuple])
def test_mapping_validator_sequence_requires_key_or_value(sequence_type):
    """Require key or value validation even with a mapping sequence."""
    with pytest.raises(
        ValueError,
        match="At least one of key_validator or value_validator",
    ):
        deep_mapping(mapping_validator=sequence_type())

