@pytest.mark.parametrize("sequence_type", [list, tuple])
@pytest.mark.parametrize("fail", [False, True])
@pytest.mark.parametrize(
    "factory_name, argument, value, expected",
    [
        ("deep_iterable", "member_validator", [1], 1),
        ("deep_iterable", "iterable_validator", [1], [1]),
        ("deep_mapping", "key_validator", {"key": 1}, "key"),
        ("deep_mapping", "value_validator", {"key": 1}, 1),
        ("deep_mapping", "mapping_validator", {"key": 1}, {"key": 1}),
    ],
)
def test_deep_validator_sequences(
    sequence_type, fail, factory_name, argument, value, expected
):
    """Apply sequence validators in order and propagate their failures."""
    from attr import validators

    inst = object()
    attribute = object()
    calls = []
    error = ValueError("validation failed")

    def first(inst, attribute, value):
        calls.append(("first", inst, attribute, value))

    def second(inst, attribute, value):
        calls.append(("second", inst, attribute, value))
        if fail:
            raise error

    def third(inst, attribute, value):
        calls.append(("third", inst, attribute, value))

    def accept(inst, attribute, value):
        pass

    kwargs = (
        {"member_validator": accept}
        if factory_name == "deep_iterable"
        else {"key_validator": accept}
    )
    kwargs[argument] = sequence_type([first, second, third])
    validator = getattr(validators, factory_name)(**kwargs)

    if fail:
        with pytest.raises(ValueError) as exc_info:
            validator(inst, attribute, value)
        assert exc_info.value is error
    else:
        validator(inst, attribute, value)

    names = ["first", "second"] if fail else ["first", "second", "third"]
    assert calls == [(name, inst, attribute, expected) for name in names]


@pytest.mark.parametrize("sequence_type", [list, tuple])
@pytest.mark.parametrize(
    "factory_name, argument, value",
    [
        ("deep_iterable", "member_validator", [1]),
        ("deep_iterable", "iterable_validator", [1]),
        ("deep_mapping", "key_validator", {"key": 1}),
        ("deep_mapping", "value_validator", {"key": 1}),
        ("deep_mapping", "mapping_validator", {"key": 1}),
    ],
)
def test_deep_validator_empty_sequences(
    sequence_type, factory_name, argument, value
):
    """Accept empty validator sequences as no-op validators."""
    from attr import validators

    def accept(inst, attribute, value):
        pass

    kwargs = {}
    if factory_name == "deep_iterable" and argument != "member_validator":
        kwargs["member_validator"] = accept
    elif factory_name == "deep_mapping" and argument == "mapping_validator":
        kwargs["key_validator"] = accept
    kwargs[argument] = sequence_type()

    getattr(validators, factory_name)(**kwargs)(None, None, value)

