import attr
import attrs
import pytest


@pytest.fixture(params=[attr.s, attrs.define, attrs.frozen])
def decorator(request):
    return request.param


@pytest.fixture(params=[False, True], ids=["dict", "slots"])
def slots(request):
    return request.param


def parameter_kinds(cls):
    return {
        name: parameter.kind
        for name, parameter in signature(cls).parameters.items()
    }


def test_explicit_false_overrides_class_default(decorator, slots):
    @decorator(kw_only=True, auto_attribs=True, slots=slots)
    class C:
        required: int
        positional: int = attrs.field(kw_only=False)
        optional: int = attrs.field(default=3, kw_only=None)

    assert C(2, required=1) == C(required=1, positional=2, optional=3)
    assert parameter_kinds(C) == {
        "positional": Parameter.POSITIONAL_OR_KEYWORD,
        "required": Parameter.KEYWORD_ONLY,
        "optional": Parameter.KEYWORD_ONLY,
    }
    assert [a.kw_only for a in attrs.fields(C)] == [True, False, True]
    with pytest.raises(TypeError):
        C(1, 2)


def test_inherited_positional_field_stays_positional(decorator, slots):
    @decorator(auto_attribs=True, slots=slots)
    class Base:
        x: int

    @decorator(kw_only=True, auto_attribs=True, slots=slots)
    class Child(Base):
        y: int

    assert Child(1, y=2) == Child(x=1, y=2)
    assert parameter_kinds(Child) == {
        "x": Parameter.POSITIONAL_OR_KEYWORD,
        "y": Parameter.KEYWORD_ONLY,
    }
    assert attrs.fields(Base).x.kw_only is False
    assert attrs.fields(Child).x.kw_only is False
    assert attrs.fields(Child).y.kw_only is True


