"""Tests for class defaults and per-field keyword-only settings."""

import inspect

import attr
import attrs
import pytest


@pytest.fixture(
    params=[
        (attr.s, False),
        (attr.s, True),
        (attrs.define, False),
        (attrs.define, True),
        (attrs.frozen, False),
        (attrs.frozen, True),
    ]
)
def decorate(request):
    """
    Exercise both APIs with and without slots.
    """
    decorator, slots = request.param

    def apply(**kwargs):
        return decorator(auto_attribs=True, slots=slots, **kwargs)

    return apply


@pytest.mark.parametrize("field", [attr.ib, attrs.field])
def test_explicit_positional_field(decorate, field):
    """
    Explicit False overrides a keyword-only class default.
    """

    @decorate(kw_only=True)
    class C:
        keyword: int
        positional: int = field(kw_only=False)

    instance = C(1, keyword=2)

    assert instance.positional == 1
    assert instance.keyword == 2
    assert attrs.fields(C).positional.kw_only is False
    assert attrs.fields(C).keyword.kw_only is True
    with pytest.raises(TypeError):
        C(1, 2)


@pytest.mark.parametrize("field", [attr.ib, attrs.field])
@pytest.mark.parametrize("kw_only", [False, True])
def test_unspecified_field_uses_class_default(decorate, field, kw_only):
    """
    Omitted and explicit None settings both inherit the class default.
    """

    @decorate(kw_only=kw_only)
    class C:
        omitted: int = field()
        explicit_none: int = field(kw_only=None)

    assert [a.kw_only for a in attrs.fields(C)] == [kw_only, kw_only]
    assert C(omitted=1, explicit_none=2).explicit_none == 2
    if kw_only:
        with pytest.raises(TypeError):
            C(1, 2)
    else:
        assert C(1, 2).omitted == 1


@pytest.mark.parametrize("base_kw_only", [False, True])
@pytest.mark.parametrize("child_kw_only", [False, True])
def test_inherited_fields_keep_their_setting(
    decorate, base_kw_only, child_kw_only
):
    """
    Subclass defaults do not change inherited fields or their metadata.
    """

    @decorate(kw_only=base_kw_only)
    class Base:
        base: int

    @decorate(kw_only=child_kw_only)
    class Child(Base):
        child: int

    assert attrs.fields(Base).base.kw_only is base_kw_only
    assert attrs.fields(Child).base.kw_only is base_kw_only
    assert attrs.fields(Child).child.kw_only is child_kw_only

    parameters = inspect.signature(Child).parameters
    for name, expected in (
        ("base", base_kw_only),
        ("child", child_kw_only),
    ):
        kind = (
            inspect.Parameter.KEYWORD_ONLY
            if expected
            else inspect.Parameter.POSITIONAL_OR_KEYWORD
        )
        assert parameters[name].kind is kind

    assert Child(base=1, child=2).child == 2


@pytest.mark.parametrize("base_kw_only", [False, True])
def test_redeclared_field_uses_subclass_default(decorate, base_kw_only):
    """
    Redeclaring an inherited field applies the subclass default.
    """

    @decorate(kw_only=base_kw_only)
    class Base:
        value: int

    @decorate(kw_only=not base_kw_only)
    class Child(Base):
        value: int

    assert attrs.fields(Base).value.kw_only is base_kw_only
    assert attrs.fields(Child).value.kw_only is not base_kw_only


def test_keyword_only_required_field_after_inherited_default(decorate):
    """
    A required keyword-only field may follow a positional default.
    """

    @decorate()
    class Base:
        base: int = 1

    @decorate(kw_only=True)
    class Child(Base):
        child: int

    assert Child(2, child=3).base == 2
    assert Child(child=3).base == 1


def test_match_args_respects_field_settings(decorate):
    """
    Pattern matching includes inherited and explicitly positional fields.
    """

    @decorate()
    class Base:
        base: int

    @decorate(kw_only=True)
    class Child(Base):
        keyword: int
        positional: int = attrs.field(kw_only=False)

    # attrs generates __match_args__ on Python versions that support it.
    if hasattr(Child, "__match_args__"):
        assert Child.__match_args__ == ("base", "positional")


def test_field_transformer_receives_resolved_settings(decorate):
    """
    Field transformers see resolved booleans and may override them.
    """
    seen = []

    def transform(cls, attributes):
        seen.extend(a.kw_only for a in attributes)
        return [a.evolve(kw_only=False) for a in attributes]

    @decorate(kw_only=True, field_transformer=transform)
    class C:
        value: int

    assert seen == [True]
    assert C(1).value == 1

import inspect

import pytest

import attr
import attrs


@pytest.mark.parametrize("decorator", [attr.s, attrs.define, attrs.frozen])
@pytest.mark.parametrize("slots", [False, True])
@pytest.mark.parametrize("kw_only", [False, True])
def test_kw_only_defaults_and_overrides(decorator, slots, kw_only):
    """
    Class defaults affect local fields and respect explicit field settings.
    """

    @decorator(auto_attribs=True, slots=slots)
    class Base:
        base: int
        base_keyword: int = attrs.field(kw_only=True)

    @decorator(auto_attribs=True, slots=slots, kw_only=kw_only)
    class Child(Base):
        value: int
        positional: int = attrs.field(kw_only=False)
        keyword: int = attrs.field(kw_only=True)

    expected = {
        "base": False,
        "base_keyword": True,
        "value": kw_only,
        "positional": False,
        "keyword": True,
    }
    parameters = inspect.signature(Child).parameters

    for name, is_keyword_only in expected.items():
        expected_kind = (
            inspect.Parameter.KEYWORD_ONLY
            if is_keyword_only
            else inspect.Parameter.POSITIONAL_OR_KEYWORD
        )
        assert parameters[name].kind == expected_kind
        assert getattr(attrs.fields(Child), name).kw_only is is_keyword_only

    assert attrs.fields(Base).base.kw_only is False
    assert attrs.fields(Base).base_keyword.kw_only is True

    if kw_only:
        instance = Child(1, 2, value=3, base_keyword=4, keyword=5)
    else:
        instance = Child(1, 3, 2, base_keyword=4, keyword=5)

    assert instance.base == 1
    assert instance.positional == 2
    assert instance.value == 3
    assert instance.base_keyword == 4
    assert instance.keyword == 5
    assert Child.__match_args__ == tuple(
        name
        for name, parameter in parameters.items()
        if parameter.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
    )


@pytest.mark.parametrize("decorator", [attr.s, attrs.define, attrs.frozen])
@pytest.mark.parametrize("slots", [False, True])
def test_inherited_keyword_only_field_keeps_its_setting(decorator, slots):
    """
