    assert instance.other == 1
    assert instance.value == 2
    assert attrs.fields(Child).value.kw_only is True
    assert attrs.fields(Child).other.kw_only is False


@pytest.mark.parametrize("decorator", [attr.s, attrs.define, attrs.frozen])
def test_redeclared_field_uses_subclass_default(decorator):
