@pytest.mark.parametrize("module_name", ["attr", "attrs"])
def test_cold_import(module_name):
    subprocess.run(
        [
            sys.executable,
            "-c",
            textwrap.dedent(
                f"""
                import importlib
                import sys

                module = importlib.import_module({module_name!r})
                deferred = {{
                    'attr._make',
                    'attr._funcs',
                    'attr._next_gen',
                    'attr._version_info',
                }}
                assert deferred.isdisjoint(sys.modules)
                assert set(module.__all__) <= set(dir(module))
                assert deferred.isdisjoint(sys.modules)

                define = module.define
                assert module.define is define
                assert module.__dict__['define'] is define

                @define
                class Example:
                    value: int

                assert module.asdict(Example(42)) == {{'value': 42}}
                assert module.asdict is module.asdict

                try:
                    module.no_such_attribute
                except AttributeError as error:
                    assert 'no_such_attribute' in str(error)
                else:
                    raise AssertionError('Unknown attribute resolved')
                """
            ),
        ],
        check=True,
    )


