def _install_lazy_modules(namespace, modules):
    """
    Defer public module imports while preserving module introspection.
    """
    previous_getattr = namespace.get("__getattr__")
    previous_dir = namespace.get("__dir__")

    def __getattr__(name):
        if name in modules:
            from importlib import import_module

            module = import_module(modules[name])
            namespace[name] = module
            return module

        if previous_getattr is not None:
            return previous_getattr(name)

        msg = (
            f"module {namespace['__name__']!r} "
            f"has no attribute {name!r}"
        )
        raise AttributeError(msg)

    def __dir__():
        names = namespace if previous_dir is None else previous_dir()
        return sorted(set(names) | modules.keys())

    namespace["__getattr__"] = __getattr__
    namespace["__dir__"] = __dir__

