@pytest.mark.parametrize("slots", [False, True])
@pytest.mark.parametrize("attribute_hook", [False, True])
def test_generator_observes_assignment(slots, attribute_hook):
    events = []

    def hook(instance, attribute, value):
        events.append(("before", getattr(instance, attribute.name)))
        yield value * 2
        events.append(("after", getattr(instance, attribute.name)))

    @define(
        slots=slots,
        on_setattr=None if attribute_hook else hook,
    )
    class C:
        value: int = field(
            default=1, on_setattr=hook if attribute_hook else None
        )

    instance = C()
    assert events == []

    instance.value = 3

    assert instance.value == 6
    assert events == [("before", 1), ("after", 6)]


@pytest.mark.parametrize("as_list", [False, True])
def test_pipeline_resumes_generators_in_reverse_order(as_list):
    events = []

    def first(instance, attribute, value):
        events.append(("first before", value))
        yield value + 1
        events.append(("first after", instance.value))

    def regular(instance, attribute, value):
        return value * 2

    def last(instance, attribute, value):
        events.append(("last before", value))
        yield value + 3
        events.append(("last after", instance.value))

    hooks = [first, regular, last]

    @define(on_setattr=hooks if as_list else setters.pipe(*hooks))
    class C:
        value: int = 0

    instance = C()
    instance.value = 4

    assert instance.value == 13
    assert events == [
        ("first before", 4),
        ("last before", 10),
        ("last after", 13),
        ("first after", 13),
    ]


def test_pipeline_unwinds_when_a_later_hook_raises():
    events = []

    def first(instance, attribute, value):
