from contextlib import ExitStack, contextmanager
from functools import lru_cache


# Add private helpers before pipe().
@lru_cache(maxsize=256)
def _cached_is_generator(hook):
    """
    Detect generator functions, importing inspect only when needed.
    """
    from inspect import isgeneratorfunction

    return isgeneratorfunction(hook)


def _is_generator(hook):
    """
    Classify hooks, including pipes and unhashable callables.
    """
    if isinstance(hook, _Pipe):
        return hook._is_generator

    try:
        hash(hook)
    except TypeError:
        from inspect import isgeneratorfunction

        return isgeneratorfunction(hook)

    return _cached_is_generator(hook)


class _Pipe:
    """
    Compose hooks while preserving generator context lifetimes.
    """

    def __init__(self, setters):
        self._setters = tuple(
            (setter, _is_generator(setter)) for setter in setters
        )
        self._is_generator = any(
            is_generator for _, is_generator in self._setters
        )

    def __call__(self, instance, attrib, new_value):
        if self._is_generator:
            return self._run_generator(instance, attrib, new_value)

        for setter, _ in self._setters:
            new_value = setter(instance, attrib, new_value)

        return new_value

    def _run_generator(self, instance, attrib, new_value):
        with ExitStack() as stack:
            for setter, is_generator in self._setters:
                if is_generator:
                    new_value = stack.enter_context(
                        contextmanager(setter)(instance, attrib, new_value)
                    )
                else:
                    new_value = setter(instance, attrib, new_value)

            yield new_value


# Replace pipe().
def pipe(*setters):
    """
    Run all *setters*, passing each one's result to the next.

    Generator hooks must yield exactly once. Their yielded values are passed
    to subsequent hooks. After assignment, generators resume in reverse order.
    If a later hook or assignment raises, active generators receive the
    exception, following the protocol of `contextlib.contextmanager`.

    .. versionadded:: 20.1.0
    .. versionchanged:: 25.4.0
       Generator hooks are supported.
    """
    return _Pipe(setters)

