class _GeneratorDetector:
    """
    Detect generator functions lazily and cache the results.
    """

    def __init__(self) -> None:
        self._cache = {}
        self._inspect = None

    def remember(self, hook, result: bool) -> None:
        """
        Cache a known result when the hook is hashable.
        """
        try:
            self._cache[hook] = result
        except TypeError:
            pass

    def __call__(self, hook) -> bool:
        try:
            return self._cache[hook]
        except (KeyError, TypeError):
            pass

        if self._inspect is None:
            from inspect import isgeneratorfunction

            self._inspect = isgeneratorfunction

        result = self._inspect(hook)
        self.remember(hook, result)
        return result


_is_generator = _GeneratorDetector()


def pipe(*setters):
    """
    Run all *setters* and return the return value of the last one.

    Generator functions must yield exactly once. Their yielded values are
    passed to the next setter. They resume after assignment, in reverse order.

    .. versionadded:: 20.1.0
    """
    hooks = tuple((setter, _is_generator(setter)) for setter in setters)

    if any(is_generator for _, is_generator in hooks):
        from contextlib import ExitStack, contextmanager

        hooks = tuple(
            (contextmanager(setter), True) if is_generator else (setter, False)
            for setter, is_generator in hooks
        )

        def wrapped_pipe(instance, attrib, new_value):
            with ExitStack() as stack:
                rv = new_value
                for setter, is_generator in hooks:
                    if is_generator:
                        rv = stack.enter_context(setter(instance, attrib, rv))
                    else:
                        rv = setter(instance, attrib, rv)

                yield rv

        _is_generator.remember(wrapped_pipe, True)
    else:

        def wrapped_pipe(instance, attrib, new_value):
            rv = new_value
            for setter, _ in hooks:
                rv = setter(instance, attrib, rv)

            return rv

        _is_generator.remember(wrapped_pipe, False)

    return wrapped_pipe

    def add_setattr(self):
        sa_attrs = {}
        for a in self._attrs:
            on_setattr = a.on_setattr or self._on_setattr
            if on_setattr and on_setattr is not setters.NO_OP:
                is_generator = setters._is_generator(on_setattr)
                if is_generator:
                    from contextlib import contextmanager

                    on_setattr = contextmanager(on_setattr)

                sa_attrs[a.name] = a, on_setattr, is_generator

        if not sa_attrs:
            return self

        if self._has_custom_setattr:
            msg = "Can't combine custom __setattr__ with on_setattr hooks."
            raise ValueError(msg)

        # docstring comes from _add_method_dunders
        def __setattr__(self, name, val):
            try:
                a, hook, is_generator = sa_attrs[name]
            except KeyError:
                _OBJ_SETATTR(self, name, val)
                return

            if is_generator:
                with hook(self, a, val) as nval:
                    _OBJ_SETATTR(self, name, nval)
            else:
                _OBJ_SETATTR(self, name, hook(self, a, val))

        self._cls_dict["__attrs_own_setattr__"] = True
        self._cls_dict["__setattr__"] = self._add_method_dunders(__setattr__)
        self._wrote_own_setattr = True

        return self

# Add to the on_setattr parameter documentation of attrs() and attrib():
#
# A generator function receives the same arguments and must yield exactly
# once. Its yielded value is assigned to the attribute, after which the
# generator resumes. Code before the yield observes the previous value;
# code after the yield observes the assigned value. An exception raised
# after assignment does not undo the assignment. Generator hooks follow
# the exception-handling rules of contextlib.contextmanager.

