def _default_init_alias_for(name: str) -> str:
    """
    Return the default __init__ parameter name for a field.

    Preserve dunder names and strip leading underscores from private names.
    """
    if name.startswith("__") and name.endswith("__"):
        return name

    return name.lstrip("_")

def _default_init_alias_for(name):
