@pytest.mark.parametrize("slots", [False, True])
@pytest.mark.parametrize(
    ("alias", "init_name", "invalid_name"),
    [
        (None, "__dunder__", "dunder__"),
        ("dunder__", "dunder__", "__dunder__"),
    ],
)
def test_evolve_uses_init_aliases(
    self, slots, alias, init_name, invalid_name
):
    """
    Evolving preserves default dunder names and respects explicit aliases.
    """

    @attr.s(slots=slots)
    class EvolveCase:
        _override = attr.ib(alias="_override")
        __mangled = attr.ib()
        __dunder__ = attr.ib(alias=alias)

    org = EvolveCase(1, 2, **{init_name: 3})

    assert org == attr.evolve(org)
    assert EvolveCase(0, 2, 3) == attr.evolve(org, _override=0)
    assert EvolveCase(1, 4, 5) == attr.evolve(
        org,
        EvolveCase__mangled=4,
        **{init_name: 5},
    )

    with pytest.raises(TypeError):
        attr.evolve(org, **{invalid_name: 5})

