// Match url.ParseQuery's first successfully decoded value, without building
// a map or decoding unrelated values.
func queryParam(rawQuery, name string) string {
	for rawQuery != "" {
		var part string
		part, rawQuery, _ = strings.Cut(rawQuery, "&")
		if part == "" || strings.Contains(part, ";") {
			continue
		}
		key, value, _ := strings.Cut(part, "=")
		key, err := url.QueryUnescape(key)
		if err != nil || key != name {
			continue
		}
		decoded, err := url.QueryUnescape(value)
		if err == nil {
			return decoded
		}
	}
	return ""
}

