// Replace JSONPBlob. Preserve the existing content-type helper if its name
// differs in this checkout.
func (c *Context) JSONPBlob(code int, callback string, b []byte) error {
	c.writeContentType(MIMEApplicationJavaScriptCharsetUTF8)
	w := c.Response()
	w.WriteHeader(code)
	for _, part := range []string{callback, "("} {
		if _, err := w.Write(responseStringBytes(part)); err != nil {
			return err
		}
	}
	if _, err := w.Write(b); err != nil {
		return err
	}
	_, err := w.Write(responseStringBytes(");"))
	return err
}

