package middleware

import (
	"crypto/rand"
	"sync"
)

const requestIDAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

type requestIDBuffer struct {
	random [64]byte
	id     [32]byte
}

var requestIDBuffers = sync.Pool{
	New: func() any { return new(requestIDBuffer) },
}

func defaultRequestID() string {
	buffer := requestIDBuffers.Get().(*requestIDBuffer)
	defer requestIDBuffers.Put(buffer)

	n := 0
	for n < len(buffer.id) {
		if _, err := rand.Read(buffer.random[:]); err != nil {
			panic(err)
		}
		for _, b := range buffer.random {
			// Reject the incomplete bucket to avoid modulo bias.
			if b >= 248 {
				continue
			}
			buffer.id[n] = requestIDAlphabet[int(b)%len(requestIDAlphabet)]
			n++
			if n == len(buffer.id) {
				break
			}
		}
	}
	// Copy before returning the buffer to the pool.
	return string(buffer.id[:])
}

