func TestQueryParamFastPath(t *testing.T) {
	queries := []string{
		"", "q=one&q=two", "q=&q=two", "q&q=two",
		"%71=hello+world", "other=%zz&q=ok", "q=%zz&q=ok",
		"q=bad;value&q=ok", "q=a%3Bb", "=empty", "&&q=x&&",
		"%zz=bad&q=ok", "q=a=b", "q=%26%3D%2B", "Q=x&q=y",
	}
	for _, raw := range queries {
		for _, name := range []string{"q", "Q", "", "missing"} {
			t.Run(raw+"/"+name, func(t *testing.T) {
				values, _ := url.ParseQuery(raw)
				want := values.Get(name)
				e := New()
				req := httptest.NewRequest(http.MethodGet, "/", nil)
				req.URL.RawQuery = raw
				c := e.NewContext(req, httptest.NewRecorder())
				if got := c.QueryParam(name); got != want {
					t.Fatalf("QueryParam = %q; want %q", got, want)
				}
				c.QueryParams()
				if got := c.QueryParam(name); got != want {
					t.Fatalf("cached QueryParam = %q; want %q", got, want)
				}
			})
		}
	}
}

func TestMiddlewareChainCompiledOnce(t *testing.T) {
	e := New()
	wrapped := 0
	called := 0
	e.Use(func(next HandlerFunc) HandlerFunc {
		wrapped++
		return func(c *Context) error {
			called++
			return next(c)
		}
	})
	e.GET("/", func(c *Context) error { return c.String(http.StatusOK, "ok") })
	for i := 0; i < 2; i++ {
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
		if rec.Code != http.StatusOK || rec.Body.String() != "ok" {
			t.Fatalf("unexpected response: %d %q", rec.Code, rec.Body.String())
		}
	}
	if wrapped != 1 || called != 2 {
		t.Fatalf("wrapped=%d called=%d; want 1 and 2", wrapped, called)
	}

	additional := 0
	e.Use(func(next HandlerFunc) HandlerFunc {
		return func(c *Context) error {
			additional++
			return next(c)
		}
	})
	e.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/", nil))
	if additional != 1 {
		t.Fatalf("new middleware called %d times; want 1", additional)
	}
}

