// responseStringBytes is only for synchronous io.Writer.Write calls.
// The resulting slice must never be modified or retained. io.Writer's
// contract requires implementations to leave the supplied bytes unchanged
// and not retain them after Write returns.
func responseStringBytes(s string) []byte {
	return unsafe.Slice(unsafe.StringData(s), len(s))
}

func writeJSONPPrefix(w io.Writer, callback string) error {
	if _, err := w.Write(responseStringBytes(callback)); err != nil {
		return err
	}
	_, err := w.Write(responseStringBytes("("))
	return err
