func queryParam(rawQuery, name string) string {
	for rawQuery != "" {
		var pair string
		pair, rawQuery, _ = strings.Cut(rawQuery, "&")
		if pair == "" || strings.Contains(pair, ";") {
			continue
		}

		key, value, _ := strings.Cut(pair, "=")
		if key != name {
			decodedKey, err := url.QueryUnescape(key)
			if err != nil || decodedKey != name {
				continue
			}
		} else if strings.ContainsAny(key, "%+") {
			// A literal match may still represent a different decoded key.
			decodedKey, err := url.QueryUnescape(key)
			if err != nil || decodedKey != name {
				continue
			}
		}

		decodedValue, err := url.QueryUnescape(value)
		if err == nil {
			return decodedValue
		}
		// ParseQuery skips malformed values and can accept a later value
		// with the same key.
	}
	return ""
