package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestMiddlewareChainCompiledOnce(t *testing.T) {
	e := New()
	compiled, called := 0, 0
	e.Use(func(next HandlerFunc) HandlerFunc {
		compiled++
		return func(c *Context) error {
			called++
			return next(c)
		}
	})
	e.GET("/", func(c *Context) error { return c.String(http.StatusOK, "ok") })

	for range 3 {
		response := httptest.NewRecorder()
		e.ServeHTTP(response, httptest.NewRequest(http.MethodGet, "/", nil))
		if response.Code != http.StatusOK || response.Body.String() != "ok" {
			t.Fatalf("unexpected response: %d %q", response.Code, response.Body.String())
		}
	}
	if compiled != 1 || called != 3 {
		t.Fatalf("compiled=%d called=%d", compiled, called)
	}

	added := 0
	e.Use(func(next HandlerFunc) HandlerFunc {
		return func(c *Context) error {
			added++
			return next(c)
		}
	})
	e.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/", nil))
	if compiled != 2 || called != 4 || added != 1 {
		t.Fatalf("chain was not invalidated: compiled=%d called=%d added=%d", compiled, called, added)
	}
}

func TestCompiledChainRoutesAfterPreMiddleware(t *testing.T) {
	e := New()
	compiled := 0
	e.Pre(func(next HandlerFunc) HandlerFunc {
		compiled++
		return func(c *Context) error {
			if c.Request().URL.Path == "/skip" {
				return c.String(http.StatusAccepted, "skipped")
			}
			c.Request().URL.Path = "/target"
			return next(c)
		}
	})
	e.GET("/target", func(c *Context) error { return c.String(http.StatusOK, "target") })

	for _, tc := range []struct {
		path string
		code int
		body string
	}{
		{"/rewrite", http.StatusOK, "target"},
		{"/skip", http.StatusAccepted, "skipped"},
		{"/rewrite-again", http.StatusOK, "target"},
	} {
		response := httptest.NewRecorder()
		e.ServeHTTP(response, httptest.NewRequest(http.MethodGet, tc.path, nil))
		if response.Code != tc.code || response.Body.String() != tc.body {
			t.Fatalf("%s: got %d %q", tc.path, response.Code, response.Body.String())
		}
	}
	if compiled != 1 {
		t.Fatalf("pre-middleware compiled %d times", compiled)
	}
}

