func TestQueryParamMatchesParseQuery(t *testing.T) {
	queries := []string{
		"", "a", "a=", "a=first&a=second", "a=&a=second",
		"a=%zz&a=valid", "a=bad;value&a=valid", "%zz=x&a=valid",
		"%61=encoded&a=plain", "a+b=space&a%2Bb=plus", "&&a=x&&",
		"=empty&=second", "a=x=y", "a=%00", "a=%FF", "%25=value",
	}
	keys := []string{"", "a", "missing", "a b", "a+b", "%", "%25", "%61"}
	for _, query := range queries {
		parsed, _ := url.ParseQuery(query)
		for _, key := range keys {
			if got, want := queryParam(query, key), parsed.Get(key); got != want {
				t.Errorf("queryParam(%q, %q)=%q, want %q", query, key, got, want)
			}
		}
	}
}

func TestContextStoreClearedOnReset(t *testing.T) {
	e := New()
	c := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())
	c.Set("previous", "secret")
	c.Reset(httptest.NewRequest(http.MethodGet, "/next", nil), httptest.NewRecorder())
	if got := c.Get("previous"); got != nil {
		t.Fatalf("store retained previous request value: %v", got)
	}
	c.Set("current", "value")
	if got := c.Get("current"); got != "value" {
		t.Fatalf("store unusable after Reset: %v", got)
	}
}

func TestStringAndHTMLResponseBytes(t *testing.T) {
	for _, value := range []string{"", "hello", "<p>世界</p>", "a\x00b\xff"} {
		for _, html := range []bool{false, true} {
			response := httptest.NewRecorder()
			c := New().NewContext(httptest.NewRequest(http.MethodGet, "/", nil), response)
			var err error
			if html {
				err = c.HTML(http.StatusCreated, value)
			} else {
				err = c.String(http.StatusCreated, value)
			}
			if err != nil || response.Code != http.StatusCreated || response.Body.String() != value {
				t.Fatalf("html=%v: code=%d body=%q err=%v", html, response.Code, response.Body.String(), err)
			}
		}
	}
}

