func TestBindMetadataPreservesFieldsAndTags(t *testing.T) {
	type Embedded struct {
		Value string `query:"nested"`
	}
	type destination struct {
		Embedded
		Value  string `query:"query_value" form:"form_value"`
		Hidden string `query:"-"`
		local  string
	}
	typ := reflect.TypeFor[destination]()
	for _, tag := range []string{"query", "form", "header", "param"} {
		fields := cachedBindFields(typ, tag)
		if len(fields) != typ.NumField() {
			t.Fatalf("%s: got %d fields", tag, len(fields))
		}
		for i, field := range fields {
			original := typ.Field(i)
			if field.index != i || !reflect.DeepEqual(field.field, original) || field.name != original.Tag.Get(tag) {
				t.Fatalf("%s: changed metadata for field %d", tag, i)
			}
		}
	}
}

