package middleware

import (
	"crypto/rand"
	"sync"
)

const requestIDAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

type requestIDBuffer struct {
	random [32]byte
	text   [32]byte
}

var requestIDBuffers = sync.Pool{
	New: func() any { return new(requestIDBuffer) },
}

func pooledRequestID() string {
	buffer := requestIDBuffers.Get().(*requestIDBuffer)
	defer requestIDBuffers.Put(buffer)

	// Rejection sampling avoids modulo bias.
	const limit = 256 - 256%len(requestIDAlphabet)
	written := 0
	for written < len(buffer.text) {
		random := buffer.random[:len(buffer.text)-written]
		if _, err := rand.Read(random); err != nil {
			// crypto/rand.Read cannot return an error with Go 1.25.
			panic(err)
		}
		for _, value := range random {
			if int(value) >= limit {
				continue
			}
			buffer.text[written] = requestIDAlphabet[int(value)%len(requestIDAlphabet)]
			written++
		}
	}

	// Copy before returning the buffer to the pool; the returned string must
	// remain independent of subsequent requests.
	return string(buffer.text[:])
}

