func TestDefaultJSONSerializer_RejectsTrailingData(t *testing.T) {
	for _, body := range []string{
		`{"id":1} {"id":2}`,
		`{"id":1} trailing`,
	} {
		t.Run(body, func(t *testing.T) {
			_, status, _ := deserializePooledJSON(strings.NewReader(body))
			if status != http.StatusBadRequest {
				t.Fatalf("status = %d, want %d", status, http.StatusBadRequest)
			}
		})
	}

	got, status, _ := deserializePooledJSON(strings.NewReader("{\"id\":1} \n\t"))
	if status != http.StatusOK || got.ID != 1 {
		t.Fatalf("trailing whitespace: status = %d, payload = %#v", status, got)
	}
}

func TestDefaultJSONSerializer_PooledBufferReuse(t *testing.T) {
	long := pooledJSONPayload{ID: 1, Name: strings.Repeat("x", 8192)}
	data, err := json.Marshal(long)
	if err != nil {
		t.Fatal(err)
	}

	for i := 0; i < 20; i++ {
		got, status, response := deserializePooledJSON(strings.NewReader(string(data)))
		if status != http.StatusOK || got != long {
			t.Fatalf("long body: status = %d, payload = %#v, response = %s", status, got, response)
		}
		got, status, response = deserializePooledJSON(strings.NewReader(`{"id":2,"name":"short"}`))
		if status != http.StatusOK || got != (pooledJSONPayload{ID: 2, Name: "short"}) {
			t.Fatalf("short body: status = %d, payload = %#v, response = %s", status, got, response)
		}
	}
}

func TestDefaultJSONSerializer_PooledBufferConcurrent(t *testing.T) {
	const workers = 32
	const iterations = 32
	var wg sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			for iteration := 0; iteration < iterations; iteration++ {
				want := pooledJSONPayload{
					ID:   worker*iterations + iteration,
					Name: fmt.Sprintf("worker-%d-iteration-%d-%s", worker, iteration, strings.Repeat("x", iteration*31)),
				}
				data, err := json.Marshal(want)
				if err != nil {
					t.Error(err)
					return
				}
				got, status, response := deserializePooledJSON(strings.NewReader(string(data)))
				if status != http.StatusOK || got != want {
					t.Errorf("status = %d, payload = %#v, want %#v, response = %s", status, got, want, response)
					return
				}
			}
		}(worker)
	}
	wg.Wait()
}

