// The supplied context omits the routing/configuration test harness.
// Extend that harness with these integration cases:
// - Disabled: a GET-only path returns 405 for HEAD.
// - Enabled: HEAD invokes the GET handler with Request.Method == HEAD.
// - Explicit HEAD wins with either registration order.
// - A specific GET path wins over a less-specific wildcard HEAD path.
// - Parameters and route middleware are preserved on fallback.
// - POST-only paths still return 405; missing paths still return 404.
// - OPTIONS and 405 Allow headers include HEAD exactly once for GET paths.
// - Using httptest.NewServer and an actual HEAD client request, verify the
//   GET handler's status and headers are returned with an empty response body.
// Tests cannot be run from the supplied context.

package middleware

import (
	"errors"
	"net/http"

	"github.com/labstack/echo/v5"
)

// AutoHandleHEAD falls back to GET when a HEAD request returns Method Not Allowed.
// Register it with Echo.Pre so routing takes place inside the middleware.
// Explicit HEAD handlers take precedence unless they return Method Not Allowed.
func AutoHandleHEAD() echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c *echo.Context) error {
			if c.Request().Method != http.MethodHead {
				return next(c)
			}

			err := next(c)
			var statusCoder echo.HTTPStatusCoder
			if !errors.As(err, &statusCoder) || statusCoder.StatusCode() != http.StatusMethodNotAllowed {
				return err
			}
			if response, _ := echo.UnwrapResponse(c.Response()); response != nil && response.Committed {
				return err
			}

			request := c.Request().Clone(c.Request().Context())
			request.Method = http.MethodGet
			c.Echo().ServeHTTP(headResponseWriter{ResponseWriter: c.Response()}, request)
			return nil
		}
	}
}

// headResponseWriter preserves response headers and status while discarding the body.
type headResponseWriter struct {
	http.ResponseWriter
}

func (w headResponseWriter) Write(body []byte) (int, error) {
	return len(body), nil
}

func (w headResponseWriter) Unwrap() http.ResponseWriter {
	return w.ResponseWriter
}

