func TestAutoHandleHEAD(t *testing.T) {
	tests := []struct {
		name         string
		method       string
		path         string
		explicitHEAD bool
		wantStatus   int
		wantBody     string
		wantHandler  string
	}{
		{name: "GET fallback", method: http.MethodHead, path: "/resource", wantStatus: http.StatusOK, wantHandler: "GET"},
		{name: "explicit HEAD", method: http.MethodHead, path: "/resource", explicitHEAD: true, wantStatus: http.StatusNoContent, wantHandler: "HEAD"},
		{name: "GET unchanged", method: http.MethodGet, path: "/resource", wantStatus: http.StatusOK, wantBody: "resource", wantHandler: "GET"},
		{name: "other method unchanged", method: http.MethodPost, path: "/resource", wantStatus: http.StatusMethodNotAllowed},
		{name: "missing route", method: http.MethodHead, path: "/missing", wantStatus: http.StatusNotFound},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e := echo.New()
			e.Pre(AutoHandleHEAD())
			e.GET("/resource", func(c *echo.Context) error {
				c.Response().Header().Set("X-Handler", "GET")
				c.Response().Header().Set("Content-Length", "8")
				return c.String(http.StatusOK, "resource")
			})
			if tt.explicitHEAD {
				e.HEAD("/resource", func(c *echo.Context) error {
					c.Response().Header().Set("X-Handler", "HEAD")
					return c.NoContent(http.StatusNoContent)
				})
