			if tt.method == http.MethodHead && !tt.explicitHEAD && tt.wantHandler == "GET" {
				if got := response.Header().Get("Content-Length"); got != "8" {
					t.Errorf("Content-Length = %q, want 8", got)
				}
			}
			if request.Method != tt.method {
				t.Errorf("request method = %q, want %q", request.Method, tt.method)
			}
		})
	}
