func TestStaticHTML5PreservesMatchedNotFound(t *testing.T) {
	root := t.TempDir()
	const index = "application index"
	if err := os.WriteFile(filepath.Join(root, "index.html"), []byte(index), 0600); err != nil {
		t.Fatal(err)
	}

	tests := []struct {
		name       string
		register   func(*echo.Echo)
		wantStatus int
		wantBody   string
	}{
		{
			name: "matched handler returns not found",
			register: func(e *echo.Echo) {
				e.GET("/missing", func(c *echo.Context) error {
					return echo.ErrNotFound
				})
			},
			wantStatus: http.StatusNotFound,
			wantBody:   `{"message":"Not Found"}`,
		},
		{
			name: "matched handler returns wrapped not found",
			register: func(e *echo.Echo) {
				e.GET("/missing", func(c *echo.Context) error {
					return fmt.Errorf("handler: %w", echo.ErrNotFound)
				})
			},
			wantStatus: http.StatusNotFound,
			wantBody:   `{"message":"Not Found"}`,
		},
		{
			name: "matched route not found handler",
			register: func(e *echo.Echo) {
				e.RouteNotFound("/*", func(c *echo.Context) error {
					return echo.ErrNotFound
				})
			},
			wantStatus: http.StatusNotFound,
			wantBody:   `{"message":"Not Found"}`,
		},
		{
			name:       "unmatched request uses HTML5 fallback",
			wantStatus: http.StatusOK,
			wantBody:   index,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e := echo.New()
			e.Use(StaticWithConfig(StaticConfig{
				Root:  root,
				HTML5: true,
			}))
			if tt.register != nil {
				tt.register(e)
			}

			req := httptest.NewRequest(http.MethodGet, "/missing", nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			if rec.Code != tt.wantStatus {
				t.Fatalf("status = %d, want %d; body = %q", rec.Code, tt.wantStatus, rec.Body.String())
			}
			if got := strings.TrimSpace(rec.Body.String()); got != tt.wantBody {
				t.Fatalf("body = %q, want %q", got, tt.wantBody)
			}
		})
	}
}

