	for _, path := range []string{"", "/*"} {
		for _, explicitFirst := range []bool{false, true} {
			name := path + "/explicit-after-middleware"
			if explicitFirst {
				name = path + "/explicit-before-middleware"
			}
			t.Run(name, func(t *testing.T) {
				e := New()
				g := e.Group("/group")
				middleware := func(next HandlerFunc) HandlerFunc {
					return func(c Context) error {
						c.Response().Header().Add("X-Group", "called")
						return next(c)
					}
				}
				register := func() {
					_, err := g.AddRoute(Route{
						Method: RouteNotFound,
						Path:   path,
						Handler: func(c Context) error {
							return c.String(http.StatusTeapot, "explicit fallback")
						},
					})
					if err != nil {
						t.Fatal(err)
					}
				}
				if explicitFirst {
					register()
				}
				g.Use(middleware)
				// Repeated Use calls also replace existing implicit fallbacks.
				g.Use(middleware)
				if !explicitFirst {
					register()
				}

				requestPath := "/group"
				if path == "/*" {
					requestPath += "/missing"
				}
				rec := httptest.NewRecorder()
				e.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, requestPath, nil))
				if rec.Code != http.StatusTeapot || rec.Body.String() != "explicit fallback" {
					t.Fatalf("got status %d, body %q", rec.Code, rec.Body.String())
				}
				if !explicitFirst && len(rec.Header().Values("X-Group")) != 2 {
					t.Fatalf("expected both group middlewares, got %v", rec.Header().Values("X-Group"))
				}
			})
		}
	}
}

