		name          string
		routePath     string
		requestPath   string
		explicitFirst bool
	}{
		{"group root", "/group", "/group", false},
		{"group wildcard", "/group/*", "/group/missing", false},
		{"existing group root", "/group", "/group", true},
		{"existing group wildcard", "/group/*", "/group/missing", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e := New()
			route := Route{
				Method: RouteNotFound,
				Path:   tc.routePath,
				Handler: func(c Context) error {
					return c.String(http.StatusTeapot, "explicit fallback")
				},
			}
			addExplicit := func() {
				t.Helper()
				if _, err := e.add(route); err != nil {
					t.Fatalf("adding explicit fallback: %v", err)
				}
			}
			if tc.explicitFirst {
				addExplicit()
			}

			g := e.Group("/group")
			middleware := func(next HandlerFunc) HandlerFunc {
				return func(c Context) error {
					return next(c)
				}
			}
			g.Use(middleware)
			// Repeated Use calls must also permit implicit route replacement.
			g.Use(middleware)

			if !tc.explicitFirst {
				addExplicit()
			}

			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, tc.requestPath, nil))
			if rec.Code != http.StatusTeapot || rec.Body.String() != "explicit fallback" {
				t.Fatalf("got status %d and body %q; want status %d and explicit fallback", rec.Code, rec.Body.String(), http.StatusTeapot)
			}

			// Once replaced, the route is explicit and normal duplicate checks apply.
			if _, err := e.add(route); err == nil {
				t.Fatal("expected duplicate explicit fallback registration to fail")
			}
		})
	}
}

func TestGroupImplicitRoutesRunMiddleware(t *testing.T) {
	e := New()
	g := e.Group("/group")
	g.Use(func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			c.Response().Header().Set("X-Group-Middleware", "executed")
			return next(c)
		}
	})

	for _, path := range []string{"/group", "/group/missing"} {
		t.Run(path, func(t *testing.T) {
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
			if rec.Code != http.StatusNotFound {
				t.Fatalf("got status %d; want %d", rec.Code, http.StatusNotFound)
			}
			if got := rec.Header().Get("X-Group-Middleware"); got != "executed" {
				t.Fatalf("group middleware header = %q; want executed", got)
			}
		})
	}
}

