		{name: "mixed case", encoding: "gZiP", decode: true},
		{name: "leading space", encoding: " gzip"},
		{name: "trailing space", encoding: "gzip "},
		{name: "multiple codings", encoding: "gzip, br"},
		{name: "other coding", encoding: "br"},
		{name: "missing encoding"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e := echo.New()
			req := httptest.NewRequest(http.MethodPost, "/", bytes.NewReader(compressed.Bytes()))
			if tc.encoding != "" {
				req.Header.Set(echo.HeaderContentEncoding, tc.encoding)
			}
			rec := httptest.NewRecorder()
			c := e.NewContext(req, rec)

			handler := middleware.Decompress()(func(c *echo.Context) error {
				body, err := io.ReadAll(c.Request().Body)
				if err != nil {
					return err
				}
				return c.Blob(http.StatusOK, "application/octet-stream", body)
			})
			if err := handler(c); err != nil {
				t.Fatal(err)
			}

			want := compressed.Bytes()
			if tc.decode {
				want = []byte(payload)
			}
			if !bytes.Equal(rec.Body.Bytes(), want) {
				t.Fatalf("response body = %q, want %q", rec.Body.Bytes(), want)
			}
		})
	}
}

