func TestCORSPreflightClassification(t *testing.T) {
	const allowedOrigin = "https://example.com"

	tests := []struct {
		name           string
		method         string
		origin         string
		requestMethod  string
		requestHeaders string
		wantPreflight  bool
		wantOrigin     string
	}{
		{
			name:   "OPTIONS without CORS headers",
			method: http.MethodOptions,
		},
		{
			name:          "OPTIONS without Origin",
			method:        http.MethodOptions,
			requestMethod: http.MethodPost,
		},
		{
			name:       "OPTIONS without request method",
			method:     http.MethodOptions,
			origin:     allowedOrigin,
			wantOrigin: allowedOrigin,
		},
		{
			name:           "request headers do not substitute for request method",
			method:         http.MethodOptions,
			origin:         allowedOrigin,
			requestHeaders: "X-Custom",
			wantOrigin:     allowedOrigin,
		},
		{
			name:   "OPTIONS with disallowed Origin without request method",
			method: http.MethodOptions,
			origin: "https://other.example.com",
		},
		{
			name:          "preflight without optional request headers",
			method:        http.MethodOptions,
			origin:        allowedOrigin,
			requestMethod: http.MethodPost,
			wantPreflight: true,
			wantOrigin:    allowedOrigin,
		},
		{
			name:           "preflight with request headers",
			method:         http.MethodOptions,
			origin:         allowedOrigin,
			requestMethod:  http.MethodPost,
			requestHeaders: "X-Custom",
			wantPreflight:  true,
			wantOrigin:     allowedOrigin,
		},
		{
			name:          "preflight with disallowed Origin",
			method:        http.MethodOptions,
			origin:        "https://other.example.com",
			requestMethod: http.MethodPost,
			wantPreflight: true,
		},
		{
			name:          "GET with preflight headers",
			method:        http.MethodGet,
			origin:        allowedOrigin,
			requestMethod: http.MethodPost,
			wantOrigin:    allowedOrigin,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e := echo.New()
			e.Use(CORSWithConfig(CORSConfig{
				AllowOrigins:  []string{allowedOrigin},
				AllowMethods:  []string{http.MethodGet, http.MethodPost},
				ExposeHeaders: []string{"X-Response"},
			}))

			called := false
			e.Add(tt.method, "/", func(c *echo.Context) error {
				called = true
				return c.String(http.StatusOK, "handler")
			})

			req := httptest.NewRequest(tt.method, "/", nil)
			req.Header.Set(echo.HeaderOrigin, tt.origin)
			req.Header.Set(echo.HeaderAccessControlRequestMethod, tt.requestMethod)
			req.Header.Set(echo.HeaderAccessControlRequestHeaders, tt.requestHeaders)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)

			wantStatus := http.StatusOK
			wantBody := "handler"
			if tt.wantPreflight {
				wantStatus = http.StatusNoContent
				wantBody = ""
			}
			if rec.Code != wantStatus {
				t.Errorf("status = %d, want %d", rec.Code, wantStatus)
			}
			if rec.Body.String() != wantBody {
				t.Errorf("body = %q, want %q", rec.Body.String(), wantBody)
			}
			if called != !tt.wantPreflight {
				t.Errorf("handler called = %v, want %v", called, !tt.wantPreflight)
			}

			wantMethods := ""
			wantHeaders := ""
			wantExpose := ""
			if tt.wantOrigin != "" {
				if tt.wantPreflight {
					wantMethods = "GET,POST"
					wantHeaders = tt.requestHeaders
				} else {
					wantExpose = "X-Response"
				}
			}
			for header, want := range map[string]string{
				echo.HeaderAccessControlAllowOrigin:   tt.wantOrigin,
				echo.HeaderAccessControlAllowMethods:  wantMethods,
				echo.HeaderAccessControlAllowHeaders:  wantHeaders,
				echo.HeaderAccessControlExposeHeaders: wantExpose,
			} {
				if got := rec.Header().Get(header); got != want {
					t.Errorf("%s = %q, want %q", header, got, want)
				}
			}
		})
	}
}

