	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
)

// This deliberately non-validating filesystem accepts parent segments and
// interprets backslashes as separators on every OS. It must only be used by tests.
type staticNonValidatingFS struct {
	root string
}

func (f staticNonValidatingFS) Open(name string) (fs.File, error) {
	name = strings.ReplaceAll(name, `\`, "/")
	return os.Open(filepath.Join(f.root, filepath.FromSlash(name)))
}

func TestStaticDirectoryHandler_nonValidatingFS(t *testing.T) {
	base := t.TempDir()
	root := filepath.Join(base, "public")
	if err := os.MkdirAll(filepath.Join(root, "x"), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(root, "admin"), 0700); err != nil {
		t.Fatal(err)
	}
	for name, contents := range map[string]string{
		filepath.Join(base, "secret.txt"):          "OUTSIDE-SECRET",
		filepath.Join(root, "admin", "secret.txt"): "GUARDED-SECRET",
		filepath.Join(root, "ok.txt"):              "public",
	} {
		if err := os.WriteFile(name, []byte(contents), 0600); err != nil {
			t.Fatal(err)
		}
	}
	fsys := staticNonValidatingFS{root: root}

	// Verify that rejection cannot be attributed to filesystem validation.
	for _, name := range []string{"../secret.txt", `..\secret.txt`} {
		f, err := fsys.Open(name)
		if err != nil {
			t.Fatal(err)
		}
		contents, readErr := io.ReadAll(f)
		closeErr := f.Close()
		if readErr != nil {
			t.Fatal(readErr)
		}
		if closeErr != nil {
			t.Fatal(closeErr)
		}
		assert.Equal(t, "OUTSIDE-SECRET", string(contents))
	}

	for _, unescape := range []bool{false, true} {
		configName := "default"
		if unescape {
			configName = "unescaping"
		}
		t.Run(configName, func(t *testing.T) {
			for _, grouped := range []bool{false, true} {
				prefix := ""
				if grouped {
					prefix = "/g"
				}
				t.Run("prefix="+prefix, func(t *testing.T) {
					e := NewWithConfig(Config{EnablePathUnescapingStaticFiles: unescape})
					if grouped {
						g := e.Group(prefix)
						g.StaticFS("/", fsys)
						g.GET("/admin/*", func(c *Context) error { return ErrForbidden })
					} else {
						e.StaticFS("/", fsys)
						e.GET("/admin/*", func(c *Context) error { return ErrForbidden })
					}

					for _, target := range []string{
						"/../secret.txt",
						"/x/../../secret.txt",
						`/..\secret.txt`,
						`/x\..\..\secret.txt`,
						`/x/..\..\secret.txt`,
						`/x\../..\secret.txt`,
						"/x/../admin/secret.txt",
						`/x\..\admin/secret.txt`,
						`/x/..\admin/secret.txt`,
						`/.\admin/secret.txt`,
						"/x%5c..%5cadmin/secret.txt",
						"/x%5C%2e%2e%5Cadmin/secret.txt",
						"/%2e%2e%5csecret.txt",
						"/x%5c..%5c..%5csecret.txt",
						"/x%255c..%255cadmin/secret.txt",
					} {
						t.Run(target, func(t *testing.T) {
							req := httptest.NewRequest(http.MethodGet, prefix+target, nil)
							rec := httptest.NewRecorder()
							e.ServeHTTP(rec, req)
							assert.Equal(t, http.StatusNotFound, rec.Code)
							assert.NotContains(t, rec.Body.String(), "SECRET")
							assert.Empty(t, rec.Header().Get("Location"))
						})
					}

					for _, tc := range []struct {
						target string
						status int
					}{
						{target: "/ok.txt", status: http.StatusOK},
						{target: "/admin/secret.txt", status: http.StatusForbidden},
					} {
						req := httptest.NewRequest(http.MethodGet, prefix+tc.target, nil)
						rec := httptest.NewRecorder()
						e.ServeHTTP(rec, req)
						assert.Equal(t, tc.status, rec.Code)
						assert.NotContains(t, rec.Body.String(), "SECRET")
						if tc.status == http.StatusOK {
							assert.Equal(t, "public", rec.Body.String())
						}
					}
				})
			}
		})
	}
}

