// staticHasDotSegment checks both separator forms on every OS. Custom filesystems
// may interpret backslashes as separators or clean names without validating them.
func staticHasDotSegment(name string) bool {
	for _, segment := range strings.Split(strings.ReplaceAll(name, `\`, "/"), "/") {
		if segment == "." || segment == ".." {
			return true
		}
	}
	return false
}

