)

// nonValidatingStaticFS deliberately cleans names without fs.ValidPath checks.
// Normalizing backslashes here exercises Windows separator semantics on every OS.
// The handler must prevent traversal before passing a name to this filesystem.
type nonValidatingStaticFS struct {
	files fstest.MapFS
	root  string
}

func (f nonValidatingStaticFS) Open(name string) (fs.File, error) {
	name = strings.ReplaceAll(name, `\`, "/")
	return f.files.Open(path.Clean(path.Join(f.root, name)))
}

func TestStaticHasDotSegment(t *testing.T) {
	for _, name := range []string{
		"../secret.txt",
		"./secret.txt",
		`..\secret.txt`,
		`.\secret.txt`,
		`x\..\secret.txt`,
		`x/..\secret.txt`,
		`x\../secret.txt`,
		`x\.\secret.txt`,
		`x\..`,
	} {
		t.Run(name, func(t *testing.T) {
			assert.True(t, staticHasDotSegment(name))
		})
	}
	for _, name := range []string{
		"file.txt",
		".../file.txt",
		"a..b/file.txt",
		`x\file.txt`,
		"%2e%2e/file.txt",
	} {
		t.Run(name, func(t *testing.T) {
			assert.False(t, staticHasDotSegment(name))
		})
	}
}

