func TestBodyLimitReadBoundaries(t *testing.T) {
	for _, tc := range []struct {
		name string
		body string
		limit int64
		want string
		tooLarge bool
	}{
		{"below", "abc", 4, "abc", false},
		{"exact", "abcd", 4, "abcd", false},
		{"above", "abcde", 4, "abcd", true},
		{"zero empty", "", 0, "", false},
		{"zero nonempty", "a", 0, "", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := &limitedReader{
				BodyLimitConfig: BodyLimitConfig{LimitBytes: tc.limit},
				reader: io.NopCloser(strings.NewReader(tc.body)),
			}
			got, err := io.ReadAll(r)
			if string(got) != tc.want {
				t.Fatalf("body = %q, want %q", got, tc.want)
			}
			if tc.tooLarge {
				if !errors.Is(err, echo.ErrStatusRequestEntityTooLarge) {
					t.Fatalf("error = %v, want 413", err)
				}
				if n, err := r.Read(make([]byte, 1)); n != 0 || !errors.Is(err, echo.ErrStatusRequestEntityTooLarge) {
					t.Fatalf("subsequent read = (%d, %v), want (0, 413)", n, err)
				}
			} else if err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestBodyLimitBindingPreserves413(t *testing.T) {
	for _, tc := range []struct {
		name string
		contentType string
		body string
	}{
		{"json", "application/json", `{"message":"abcdefghijklmnopqrstuvwxyz"}`},
		{"xml", "application/xml", `<payload><message>abcdefghijklmnopqrstuvwxyz</message></payload>`},
		{"form", "application/x-www-form-urlencoded", "message=abcdefghijklmnopqrstuvwxyz"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e := echo.New()
			req := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(tc.body))
			req.ContentLength = -1
			req.Header.Set("Content-Type", tc.contentType)
			c := e.NewContext(req, httptest.NewRecorder())
			err := BodyLimit(16)(func(c *echo.Context) error {
				var target struct {
					Message string `json:"message" xml:"message" form:"message"`
				}
				return c.Bind(&target)
			})(c)
			if err != echo.ErrStatusRequestEntityTooLarge {
				t.Fatalf("binding error = %v, want 413", err)
			}
		})
	}
}

func TestBodyLimitReaderLivesWithRequest(t *testing.T) {
	e := echo.New()
	var bodies []io.ReadCloser
	handler := BodyLimit(64)(func(c *echo.Context) error {
		bodies = append(bodies, c.Request().Body)
		return nil
	})
	for _, body := range []string{"first", "second"} {
		req := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(body))
		if err := handler(e.NewContext(req, httptest.NewRecorder())); err != nil {
			t.Fatal(err)
		}
	}
	if bodies[0] == bodies[1] {
		t.Fatal("requests share a body reader")
	}
	for index, want := range []string{"first", "second"} {
		got, err := io.ReadAll(bodies[index])
		if err != nil || string(got) != want {
			t.Fatalf("request %d body = %q, error = %v; want %q", index, got, err, want)
		}
	}
}

