func TestBodyLimitCapsUnderlyingReads(t *testing.T) {
	body := strings.NewReader(strings.Repeat("x", 1024))
	r := &limitedReader{
		BodyLimitConfig: BodyLimitConfig{LimitBytes: 8},
		reader:          io.NopCloser(body),
	}
	n, err := r.Read(make([]byte, 1024))
	if n != 0 || !errors.Is(err, echo.ErrStatusRequestEntityTooLarge) {
		t.Fatalf("Read() = (%d, %v), want (0, 413)", n, err)
	}
	if consumed := 1024 - body.Len(); consumed != 9 {
		t.Fatalf("consumed %d bytes, want 9 including overflow probe", consumed)
	}
	n, err = r.Read(make([]byte, 1024))
	if n != 0 || !errors.Is(err, echo.ErrStatusRequestEntityTooLarge) {
		t.Fatalf("subsequent Read() = (%d, %v), want (0, 413)", n, err)
	}
	if body.Len() != 1015 {
		t.Fatal("subsequent Read consumed more of the body")
	}
}

