func TestBindValue_OpenAPITimeFormats(t *testing.T) {
	utc := time.Date(2026, time.November, 1, 12, 34, 56, 0, time.UTC)
	tests := []struct {
		name    string
		format  TimeLayout
		value   string
		want    time.Time
		wantErr bool
	}{
		{name: "untagged", value: "2026-11-01T12:34:56Z", want: utc},
		{name: "date-time UTC", format: "date-time", value: "2026-11-01T12:34:56Z", want: utc},
		{name: "date-time offset", format: "date-time", value: "2026-11-01T14:34:56+02:00", want: utc},
		{name: "date-time fraction", format: "date-time", value: "2026-11-01T12:34:56.123456789Z", want: utc.Add(123456789)},
		{name: "date-time requires zone", format: "date-time", value: "2026-11-01T12:34:56", wantErr: true},
		{name: "local", format: "date-time-local", value: "2026-11-01T12:34:56", want: utc},
		{name: "local fraction", format: "date-time-local", value: "2026-11-01T12:34:56.123456789", want: utc.Add(123456789)},
		{name: "local rejects Z", format: "date-time-local", value: "2026-11-01T12:34:56Z", wantErr: true},
		{name: "local rejects offset", format: "date-time-local", value: "2026-11-01T12:34:56+02:00", wantErr: true},
		{name: "local rejects negative offset", format: "date-time-local", value: "2026-11-01T12:34:56-05:00", wantErr: true},
		{name: "local requires seconds", format: "date-time-local", value: "2026-11-01T12:34", wantErr: true},
		{name: "date", format: "date", value: "2026-11-01", want: time.Date(2026, time.November, 1, 0, 0, 0, 0, time.UTC)},
		{name: "date rejects time", format: "date", value: "2026-11-01T12:34:56", wantErr: true},
		{name: "date rejects zone", format: "date", value: "2026-11-01Z", wantErr: true},
		{name: "invalid date", format: "date", value: "2026-02-30", wantErr: true},
		{name: "Go layout", format: "02/01/2006 15:04:05", value: "01/11/2026 12:34:56", want: utc},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			sentinel := time.Date(2000, time.January, 1, 0, 0, 0, 0, time.UTC)
			got := sentinel
			var opts []any
			if tt.format != "" {
				opts = append(opts, tt.format)
