					t.Fatal("expected a parsing error")
				}
				if got != sentinel {
					t.Fatalf("failed parsing changed destination to %v", got)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if !got.Equal(tt.want) || got.Location() != time.UTC {
				t.Fatalf("got %v (%v), want %v (UTC)", got, got.Location(), tt.want)
