			format: "date-time-local",
			value:  "2026-11-01T12:34:56",
			want:   time.Date(2026, 11, 1, 12, 34, 56, 0, time.UTC),
		},
		{
			name:   "date-time-local fractional seconds",
			format: "date-time-local",
			value:  "2026-11-01T12:34:56.123456789",
			want:   time.Date(2026, 11, 1, 12, 34, 56, 123456789, time.UTC),
		},
