			value:  "2026-11-01",
			want:   time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC),
		},
		{
			name:   "Go layout",
			format: "02/01/2006 15:04",
			value:  "01/11/2026 12:34",
			want:   time.Date(2026, 11, 1, 12, 34, 0, 0, time.UTC),
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var got time.Time
			if err := bindValue(tt.value, &got, tt.format); err != nil {
				t.Fatal(err)
			}
			if !got.Equal(tt.want) || got.Location() != time.UTC {
				t.Fatalf("got %v (%v), want %v (UTC)", got, got.Location(), tt.want)
			}
			if tt.format == "date-time" {
				var untagged time.Time
				if err := bindValue(tt.value, &untagged); err != nil {
					t.Fatal(err)
				}
				if got != untagged {
					t.Fatalf("tagged value %v differs from untagged value %v", got, untagged)
				}
			}
		})
	}
}

