// Uses net/http, net/http/httptest, and testing in the existing import block.

func TestDefaultRouterRouteGrowsExistingContextPathValues(t *testing.T) {
	for _, initial := range []struct {
		name string
		path string
		url  string
	}{
		{name: "no parameters", path: "/seed", url: "/seed"},
		{name: "one parameter", path: "/seed/:one", url: "/seed/first"},
	} {
		t.Run(initial.name, func(t *testing.T) {
			e := New()
			handler := func(c *Context) error { return nil }
			if _, err := e.add(Route{
				Method: http.MethodGet, Path: initial.path, Handler: handler,
			}); err != nil {
				t.Fatal(err)
			}

			req := httptest.NewRequest(http.MethodGet, initial.url, nil)
			c := e.NewContext(req, httptest.NewRecorder())
			e.router.Route(c)

			if _, err := e.add(Route{
				Method: http.MethodGet, Path: "/grown/:one/:two/:three", Handler: handler,
			}); err != nil {
				t.Fatal(err)
			}

			req.URL.Path = "/grown/a/b/c"
			e.router.Route(c)
			want := PathValues{
				{Name: "one", Value: "a"},
				{Name: "two", Value: "b"},
				{Name: "three", Value: "c"},
			}
			check := func() {
				t.Helper()
				got := c.PathValues()
				if len(got) != len(want) {
					t.Fatalf("PathValues length = %d, want %d", len(got), len(want))
				}
				for i := range want {
					if got[i] != want[i] {
						t.Fatalf("PathValues[%d] = %#v, want %#v", i, got[i], want[i])
					}
				}
			}
			check()
			backing := &c.PathValues()[0]

			// Routing a shorter path must preserve the grown allocation.
			req.URL.Path = initial.url
			e.router.Route(c)
			if cap(c.PathValues()) < len(want) {
				t.Fatal("Context did not retain the grown PathValues capacity")
			}

			req.URL.Path = "/grown/a/b/c"
			e.router.Route(c)
			check()
			if &c.PathValues()[0] != backing {
				t.Fatal("routing again replaced the grown PathValues allocation")
			}
		})
	}
}

