// Add net/http and net/http/httptest to the imports if absent.

func TestRouterRouteGrowsExistingContextPathValues(t *testing.T) {
	for _, firstPath := range []string{"/new/one/two", "/missing"} {
		t.Run(firstPath, func(t *testing.T) {
			e := New()
			handler := func(c *Context) error { return nil }
			e.GET("/old/:first", handler)

			req := httptest.NewRequest(http.MethodGet, "/old/initial", nil)
			c := e.NewContext(req, httptest.NewRecorder())
			e.router.Route(c)
			initialCapacity := cap(c.PathValues())

			e.GET("/new/:first/:second", handler)
			req.URL.Path = firstPath
			e.router.Route(c)

			if got := cap(c.PathValues()); got < 2 {
				t.Fatalf("PathValues capacity = %d, want at least 2 (initially %d)", got, initialCapacity)
			}
			storage := c.PathValues()[:cap(c.PathValues())]
			first := &storage[0]

			// Reuse the context to verify both parameter extraction and retention
			// of the allocation, including when the first request returned 404.
			for range 2 {
				req.URL.Path = "/new/one/two"
				e.router.Route(c)
				values := c.PathValues()
				if len(values) != 2 {
					t.Fatalf("PathValues length = %d, want 2", len(values))
				}
				if values[0].Name != "first" || values[0].Value != "one" ||
					values[1].Name != "second" || values[1].Value != "two" {
					t.Fatalf("unexpected PathValues: %#v", values)
				}
				if &values[0] != first {
					t.Fatal("grown PathValues storage was not retained")
				}
			}
		})
	}
}

