import "context"

// ValidatorWithContext is an optional extension of Validator used by
// Context.ValidateCtx. Implementations must also implement Validate so they can
// be assigned to Echo.Validator.
//
// Context.Validate always calls Validate. Context.ValidateCtx prefers ValidateCtx
// and falls back to Validate when this interface is not implemented.
//
// Wrappers must explicitly forward ValidateCtx when they need to preserve
// context-aware validation. Embedding only Validator does not expose ValidateCtx.
// Embedding a concrete validator may promote ValidateCtx; wrappers that override
// Validate must also override ValidateCtx if that behavior should apply to both
// entry points.
//
// Implementations are responsible for observing cancellation and deadlines and
// returning appropriate errors. Echo passes the context through without checking
// cancellation or translating validation errors.
type ValidatorWithContext interface {
	Validator
	ValidateCtx(ctx context.Context, i any) error
}

// Validate validates i using the registered validator's Validate method.
// Use ValidateCtx to explicitly opt into context-aware validation.
func (c *Context) Validate(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	return c.echo.Validator.Validate(i)
}

// ValidateCtx validates i using the current request's context when the registered
// validator implements ValidatorWithContext. Otherwise, it calls Validate.
// The request context is read on each invocation, including after SetRequest.
// Context-aware validation requires a non-nil request.
//
// Cancellation and deadlines are handled by the validator. ValidateCtx does not
// skip validation for a canceled context and returns the validator's error unchanged.
func (c *Context) ValidateCtx(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	if v, ok := c.echo.Validator.(ValidatorWithContext); ok {
		return v.ValidateCtx(c.request.Context(), i)
	}
	return c.echo.Validator.Validate(i)
}

// Add these standard-library imports if they are not already present.
import (
	"context"
	"errors"
)

type contextValidator struct {
	validateCalls    int
	validateCtxCalls int
	gotContext       context.Context
	gotValue         any
	validateErr      error
	validateCtxErr   error
}

func (v *contextValidator) Validate(i any) error {
	v.validateCalls++
	v.gotValue = i
	return v.validateErr
}

func (v *contextValidator) ValidateCtx(ctx context.Context, i any) error {
	v.validateCtxCalls++
	v.gotContext = ctx
	v.gotValue = i
	return v.validateCtxErr
}

var _ ValidatorWithContext = (*contextValidator)(nil)

func TestContext_ValidateCtx(t *testing.T) {
	t.Run("validator not registered", func(t *testing.T) {
		c := New().NewContext(nil, nil)
		assert.ErrorIs(t, c.ValidateCtx(struct{}{}), ErrValidatorNotRegistered)
	})

	t.Run("legacy validator", func(t *testing.T) {
		e := New()
		e.Validator = &validator{}
		c := e.NewContext(nil, nil)
		assert.NoError(t, c.ValidateCtx(struct{}{}))
	})

	t.Run("context-aware validation is explicit", func(t *testing.T) {
		legacyErr := errors.New("legacy validation")
		ctxErr := errors.New("context validation")
		v := &contextValidator{validateErr: legacyErr, validateCtxErr: ctxErr}
		e := New()
		e.Validator = v
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		c := e.NewContext(req, httptest.NewRecorder())
		value := &struct{ Name string }{Name: "example"}

		assert.Same(t, legacyErr, c.Validate(value))
		assert.Equal(t, 1, v.validateCalls)
		assert.Equal(t, 0, v.validateCtxCalls)

		assert.Same(t, ctxErr, c.ValidateCtx(value))
		assert.Equal(t, 1, v.validateCalls)
		assert.Equal(t, 1, v.validateCtxCalls)
		assert.Equal(t, req.Context(), v.gotContext)
		assert.Same(t, value, v.gotValue)
	})

	t.Run("uses current request after replacement", func(t *testing.T) {
		type contextKey struct{}
		first := context.WithValue(context.Background(), contextKey{}, "first")
		second := context.WithValue(context.Background(), contextKey{}, "second")
		v := &contextValidator{}
		e := New()
		e.Validator = v
		req := httptest.NewRequest(http.MethodGet, "/", nil).WithContext(first)
		c := e.NewContext(req, httptest.NewRecorder())

		assert.NoError(t, c.ValidateCtx(struct{}{}))
		assert.Equal(t, first, v.gotContext)
		assert.Equal(t, "first", v.gotContext.Value(contextKey{}))

		c.SetRequest(req.WithContext(second))
		assert.NoError(t, c.ValidateCtx(struct{}{}))
		assert.Equal(t, second, v.gotContext)
		assert.Equal(t, "second", v.gotContext.Value(contextKey{}))
		assert.Equal(t, 2, v.validateCtxCalls)
		assert.Equal(t, 0, v.validateCalls)
	})

	t.Run("validator handles cancellation", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		cancel()
		v := &contextValidator{}
		e := New()
		e.Validator = v
		req := httptest.NewRequest(http.MethodGet, "/", nil).WithContext(ctx)
		c := e.NewContext(req, httptest.NewRecorder())

		assert.NoError(t, c.ValidateCtx(struct{}{}))
		assert.Equal(t, 1, v.validateCtxCalls)
		assert.ErrorIs(t, v.gotContext.Err(), context.Canceled)

		v.validateCtxErr = context.Canceled
		assert.ErrorIs(t, c.ValidateCtx(struct{}{}), context.Canceled)
		assert.Equal(t, 2, v.validateCtxCalls)
		assert.Equal(t, 0, v.validateCalls)
	})

	t.Run("embedding Validator uses legacy fallback", func(t *testing.T) {
		legacyErr := errors.New("legacy validation")
		v := &contextValidator{validateErr: legacyErr}
		wrapper := &struct{ Validator }{Validator: v}
		e := New()
		e.Validator = wrapper
		c := e.NewContext(nil, nil)

		assert.Same(t, legacyErr, c.ValidateCtx(struct{}{}))
		assert.Equal(t, 1, v.validateCalls)
		assert.Equal(t, 0, v.validateCtxCalls)
	})
}

// ValidatorCtx is optionally implemented by a registered Validator to support
// validation with the current HTTP request's context. Implementations must also
// implement Validator so they can be assigned to Echo.Validator.
//
// Context.ValidateCtx prefers ValidateCtx over Validate when both are available.
// Context.Validate always calls Validate.
//
// Wrappers embedding a context-aware validator inherit its ValidateCtx method.
// A wrapper that customizes Validate must also implement ValidateCtx if that
// customization should apply to context-aware validation.
//
// Implementations are responsible for observing cancellation and deadlines and
// returning any appropriate error. Echo passes the context through without
// checking cancellation or replacing the returned error.
 type ValidatorCtx interface {
	ValidateCtx(ctx context.Context, i any) error
}

// Validate validates i using the registered Validator's Validate method.
// Use ValidateCtx to explicitly request context-aware validation.
func (c *Context) Validate(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	return c.echo.Validator.Validate(i)
}

// ValidateCtx validates i using the current HTTP request's context when the
// registered Validator implements ValidatorCtx. Otherwise it falls back to
// Validate. It returns ErrValidatorNotRegistered when no validator is registered.
//
// The request context is read on every call, including after SetRequest replaces
// the request. Context-aware validators receive canceled contexts and are
// responsible for handling cancellation; their errors are returned unchanged.
func (c *Context) ValidateCtx(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	if v, ok := c.echo.Validator.(ValidatorCtx); ok {
		return v.ValidateCtx(c.Request().Context(), i)
	}
	return c.echo.Validator.Validate(i)
}

