type validateCtxLegacyValidator struct {
	calls int
	input any
	err   error
}

func (v *validateCtxLegacyValidator) Validate(i any) error {
	v.calls++
	v.input = i
	return v.err
}

type validateCtxValidator struct {
	validateCtxLegacyValidator
	callsCtx int
	ctx      context.Context
	inputCtx any
	errCtx   error
}

func (v *validateCtxValidator) ValidateCtx(ctx context.Context, i any) error {
	v.callsCtx++
	v.ctx = ctx
	v.inputCtx = i
	return v.errCtx
}

func TestContext_ValidateCtxNotRegistered(t *testing.T) {
	e := New()
	c := e.NewContext(nil, nil)
	if err := c.ValidateCtx(struct{}{}); err != ErrValidatorNotRegistered {
		t.Fatalf("ValidateCtx error = %v, want %v", err, ErrValidatorNotRegistered)
	}
}

func TestContext_ValidateCtxLegacyFallback(t *testing.T) {
	validationErr := errors.New("validation failed")
	for _, wantErr := range []error{nil, validationErr} {
		e := New()
		v := &validateCtxLegacyValidator{err: wantErr}
		e.Validator = v
		c := e.NewContext(nil, nil)
		input := &struct{ Name string }{Name: "test"}

		if err := c.ValidateCtx(input); err != wantErr {
			t.Fatalf("ValidateCtx error = %v, want %v", err, wantErr)
		}
		if v.calls != 1 || v.input != input {
			t.Fatalf("legacy validator received calls=%d, input=%v", v.calls, v.input)
		}
	}
}

func TestContext_ValidateCtxPrecedence(t *testing.T) {
	validationErr := errors.New("context validation failed")
	for _, wantErr := range []error{nil, validationErr} {
		e := New()
		v := &validateCtxValidator{errCtx: wantErr}
		e.Validator = v
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		c := e.NewContext(req, httptest.NewRecorder())
		input := &struct{}{}

		if err := c.ValidateCtx(input); err != wantErr {
			t.Fatalf("ValidateCtx error = %v, want %v", err, wantErr)
		}
		if v.calls != 0 || v.callsCtx != 1 {
			t.Fatalf("validator calls: legacy=%d, context=%d", v.calls, v.callsCtx)
		}
		if v.ctx != req.Context() || v.inputCtx != input {
			t.Fatal("context validator did not receive the request context and input")
		}
	}
}

func TestContext_ValidateRemainsExplicit(t *testing.T) {
	e := New()
	wantErr := errors.New("legacy validation failed")
	v := &validateCtxValidator{
		validateCtxLegacyValidator: validateCtxLegacyValidator{err: wantErr},
	}
	e.Validator = v
	c := e.NewContext(nil, nil)
	input := &struct{}{}

	if err := c.Validate(input); err != wantErr {
		t.Fatalf("Validate error = %v, want %v", err, wantErr)
	}
	if v.calls != 1 || v.callsCtx != 0 || v.input != input {
		t.Fatalf("unexpected validator dispatch: legacy=%d, context=%d", v.calls, v.callsCtx)
	}
}

func TestContext_ValidateCtxRequestReplacement(t *testing.T) {
	type contextKey struct{}
	e := New()
	v := &validateCtxValidator{}
	e.Validator = v
	originalCtx := context.WithValue(context.Background(), contextKey{}, "original")
	req := httptest.NewRequest(http.MethodGet, "/", nil).WithContext(originalCtx)
	c := e.NewContext(req, httptest.NewRecorder())

	if err := c.ValidateCtx(struct{}{}); err != nil {
		t.Fatal(err)
	}
	if v.ctx != originalCtx {
		t.Fatal("first validation did not receive the original request context")
	}

	replacementCtx := context.WithValue(context.Background(), contextKey{}, "replacement")
	c.SetRequest(req.WithContext(replacementCtx))
	if err := c.ValidateCtx(struct{}{}); err != nil {
		t.Fatal(err)
	}
	if v.ctx != replacementCtx || v.ctx.Value(contextKey{}) != "replacement" {
		t.Fatal("validation did not receive the replacement request context")
	}
	if v.callsCtx != 2 || v.calls != 0 {
		t.Fatalf("unexpected validator dispatch: legacy=%d, context=%d", v.calls, v.callsCtx)
	}
}

func TestContext_ValidateCtxCancellation(t *testing.T) {
	for _, wantErr := range []error{nil, context.Canceled} {
		e := New()
		v := &validateCtxValidator{errCtx: wantErr}
		e.Validator = v
		ctx, cancel := context.WithCancel(context.Background())
		cancel()
		req := httptest.NewRequest(http.MethodGet, "/", nil).WithContext(ctx)
		c := e.NewContext(req, httptest.NewRecorder())

		if err := c.ValidateCtx(struct{}{}); err != wantErr {
			t.Fatalf("ValidateCtx error = %v, want %v", err, wantErr)
		}
		if v.callsCtx != 1 || v.ctx != ctx || v.ctx.Err() != context.Canceled {
			t.Fatal("canceled request context was not passed to the validator")
		}
	}
}

