// Context.Validate always calls Validate.
//
// Wrappers embedding a context-aware validator inherit its ValidateCtx method.
// A wrapper that customizes Validate must also implement ValidateCtx if that
// customization should apply to context-aware validation.
//
// Implementations are responsible for observing cancellation and deadlines and
// returning any appropriate error. Echo passes the context through without
// checking cancellation or replacing the returned error.
 type ValidatorCtx interface {
	ValidateCtx(ctx context.Context, i any) error
}

// Validate validates i using the registered Validator's Validate method.
// Use ValidateCtx to explicitly request context-aware validation.
func (c *Context) Validate(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	return c.echo.Validator.Validate(i)
}

// ValidateCtx validates i using the current HTTP request's context when the
// registered Validator implements ValidatorCtx. Otherwise it falls back to
// Validate. It returns ErrValidatorNotRegistered when no validator is registered.
//
// The request context is read on every call, including after SetRequest replaces
// the request. Context-aware validators receive canceled contexts and are
// responsible for handling cancellation; their errors are returned unchanged.
func (c *Context) ValidateCtx(i any) error {
	if c.echo.Validator == nil {
		return ErrValidatorNotRegistered
	}
	if v, ok := c.echo.Validator.(ValidatorCtx); ok {
		return v.ValidateCtx(c.Request().Context(), i)
	}
	return c.echo.Validator.Validate(i)
}

