/* Add before uv__iou_get_sqe().
 *
 * Use synchronous cancellation so uv_cancel() can report whether the kernel
 * accepted the cancellation. This operation requires Linux 6.0 or newer;
 * unsupported kernels continue to return UV_EBUSY.
 */
#define UV__IORING_REGISTER_SYNC_CANCEL 24

struct uv__iou_sync_cancel {
  uint64_t addr;
  int32_t fd;
  uint32_t flags;
  int64_t timeout_sec;
  int64_t timeout_nsec;
  uint64_t reserved[4];
};

static void uv__iou_work(struct uv__work* w) {
  (void) w;
  abort();  /* Marks requests owned by io_uring; never executed. */
}

int uv__iou_fs_cancel(uv_fs_t* req) {
  struct uv__iou_sync_cancel cancel;
  struct uv__iou* iou;
  int rc;

  if (req->work_req.work != uv__iou_work)
    return UV_ENOSYS;  /* Let uv__work_cancel() handle thread pool requests. */

  iou = &uv__get_internal_fields(req->loop)->iou;
  memset(&cancel, 0, sizeof(cancel));
  cancel.addr = (uintptr_t) req;
  cancel.fd = -1;
  cancel.timeout_sec = -1;
  cancel.timeout_nsec = -1;

  do
    rc = uv__io_uring_register(iou->ringfd,
                              UV__IORING_REGISTER_SYNC_CANCEL,
                              &cancel,
                              1);
  while (rc == -1 && errno == EINTR);

  /* Completion, including delivery of UV_ECANCELED, still goes through the
   * original CQE. Never unregister the request or invoke its callback here.
   */
  return rc >= 0 ? 0 : UV_EBUSY;
}

/* In uv__iou_get_sqe(), on its successful path, before returning the SQE:
 * initialize the work record used by uv__work_cancel(). Do this before
 * publishing the SQE to the kernel.
 */
  req->work_req.loop = loop;
  req->work_req.work = uv__iou_work;
  uv__queue_init(&req->work_req.wq);

/* In uv__poll_io_uring(), immediately after decrementing in_flight: */
    uv__req_unregister(loop);
    iou->in_flight--;
    req->work_req.work = NULL;

