/* Add at file scope. */
#ifdef __linux__
static uv_fs_t iouring_cancel_req;
static uv_timer_t iouring_cancel_timer;
static uv_buf_t iouring_cancel_buf;
static int iouring_cancel_fds[2];
static int iouring_cancel_status;
static int iouring_cancel_cb_called;
static char iouring_cancel_byte;

static void iouring_cancel_cb(uv_fs_t* req) {
  ASSERT_PTR_EQ(req, &iouring_cancel_req);
  ASSERT_EQ(0, iouring_cancel_cb_called);
  iouring_cancel_cb_called++;

  if (iouring_cancel_status == 0)
    ASSERT_EQ(UV_ECANCELED, req->result);
  else
    ASSERT(req->result == 1 || req->result == UV_ECANCELED);

  uv_fs_req_cleanup(req);
}

static void iouring_cancel_timer_cb(uv_timer_t* timer) {
  uv_fs_t req;
  uv_buf_t buf;
  char byte;

  iouring_cancel_status = uv_cancel((uv_req_t*) &iouring_cancel_req);
  ASSERT(iouring_cancel_status == 0 ||
         iouring_cancel_status == UV_EBUSY);

  /* Also release a read that fell back to a running thread pool worker, or
   * that could not be cancelled by this kernel.
   */
  byte = 'x';
  buf = uv_buf_init(&byte, 1);
  ASSERT_EQ(1, uv_fs_write(NULL,
                           &req,
                           iouring_cancel_fds[1],
                           &buf,
                           1,
                           -1,
                           NULL));
  uv_fs_req_cleanup(&req);
  uv_close((uv_handle_t*) timer, NULL);
}
#endif

TEST_IMPL(fs_cancel_io_uring) {
#ifdef __linux__
  uv_loop_t loop;

  iouring_cancel_status = UV_EBUSY;
  iouring_cancel_cb_called = 0;
  ASSERT_OK(pipe(iouring_cancel_fds));
  ASSERT_OK(uv_loop_init(&loop));
  ASSERT_OK(uv_timer_init(&loop, &iouring_cancel_timer));

  iouring_cancel_buf = uv_buf_init(&iouring_cancel_byte, 1);
  ASSERT_OK(uv_fs_read(&loop,
                       &iouring_cancel_req,
                       iouring_cancel_fds[0],
                       &iouring_cancel_buf,
                       1,
                       -1,
                       iouring_cancel_cb));
  ASSERT_OK(uv_timer_start(&iouring_cancel_timer,
                           iouring_cancel_timer_cb,
                           10,
                           0));
  ASSERT_OK(uv_run(&loop, UV_RUN_DEFAULT));
  ASSERT_EQ(1, iouring_cancel_cb_called);
  ASSERT_OK(uv_loop_close(&loop));
  ASSERT_OK(close(iouring_cancel_fds[0]));
  ASSERT_OK(close(iouring_cancel_fds[1]));

  if (iouring_cancel_status == UV_EBUSY)
    RETURN_SKIP("io_uring cancellation unavailable; run with "
                "UV_USE_IO_URING=1 on Linux 6.0 or newer");

  return 0;
#else
  RETURN_SKIP("Linux only");
#endif
}

