/* Add after uv__io_uring_register(). */
int uv__iou_fs_cancel(uv_loop_t* loop, uv_fs_t* req) {
  struct uv__io_uring_sync_cancel_reg cancel;
  struct uv__iou* iou;
  int rc;

  iou = &uv__get_internal_fields(loop)->iou;
  if (iou->ringfd == -1)
    return UV_EBUSY;

  memset(&cancel, 0, sizeof(cancel));
  cancel.addr = (uintptr_t) req;
  cancel.fd = -1;
  cancel.timeout.tv_sec = -1;
  cancel.timeout.tv_nsec = -1;

  /* Confirm cancellation before reporting success. The original request's
   * CQE still delivers its callback and releases its active request count.
   */
  do
    rc = uv__io_uring_register(iou->ringfd,
                               UV__IORING_REGISTER_SYNC_CANCEL,
                               &cancel,
                               1);
  while (rc == -1 && errno == EINTR);

  /* Includes unsupported kernels and requests that have already completed. */
  return rc < 0 ? UV_EBUSY : 0;
}

