TEST_IMPL(fs_cancel_io_uring) {
#if defined(__linux__)
  uv_os_uname_t info;
  uv_loop_t loop;
  uv_fs_t req;
  uv_buf_t buf;
  uv_file fds[2];
  unsigned int major;
  unsigned int i;
  int using_io_uring;
  int rc;
  char byte;

  ASSERT_OK(uv_os_uname(&info));
  ASSERT_EQ(1, sscanf(info.release, "%u", &major));
  if (major < 6)
    RETURN_SKIP("io_uring synchronous cancellation requires Linux 6.0");

  ASSERT_OK(uv_os_setenv("UV_USE_IO_URING", "1"));
  ASSERT_OK(uv_loop_init(&loop));
  ASSERT_OK(uv_pipe(fds, 0, 0));

  iou_cancel_cb_called = 0;
  iou_cancel_expected_result = UV_ECANCELED;
  buf = uv_buf_init(&byte, 1);
  ASSERT_OK(uv_fs_read(&loop, &req, fds[0], &buf, 1, -1,
                      iou_cancel_read_cb));

  using_io_uring = req.work_req.done == NULL;
  rc = UV_EBUSY;
  if (using_io_uring) {
    /* SQPOLL may not have consumed the submitted read yet. Keep the loop
     * stopped so the request and its completion remain available.
     */
    for (i = 0; i < 1000; i++) {
      rc = uv_cancel((uv_req_t*) &req);
      if (rc != UV_EBUSY)
        break;
      uv_sleep(1);
    }
  }

  if (rc != 0) {
    iou_cancel_expected_result = 1;
    iou_cancel_unblock(&loop, fds[1]);
  }

  /* Cancellation must leave callback delivery to the event loop. */
  ASSERT_EQ(0, iou_cancel_cb_called);
  ASSERT_OK(uv_run(&loop, UV_RUN_DEFAULT));
  ASSERT_EQ(1, iou_cancel_cb_called);

  ASSERT_OK(uv_fs_close(&loop, &req, fds[0], NULL));
  uv_fs_req_cleanup(&req);
  ASSERT_OK(uv_fs_close(&loop, &req, fds[1], NULL));
  uv_fs_req_cleanup(&req);
  ASSERT_OK(uv_loop_close(&loop));

  if (!using_io_uring)
    RETURN_SKIP("io_uring filesystem requests are unavailable");

  ASSERT_OK(rc);
  return 0;
#else
  RETURN_SKIP("Linux only");
#endif
}

