/* Identifies requests owned by io_uring rather than the thread pool. */
void uv__iou_fs_work(struct uv__work* w) {
  abort();
}

int uv__iou_fs_cancel(uv_fs_t* req) {
  struct uv__io_uring_sync_cancel_reg arg;
  struct uv__iou* iou;
  int err;
  int rc;

  iou = &uv__get_internal_fields(req->loop)->iou;
  memset(&arg, 0, sizeof(arg));
  arg.addr = (uintptr_t) req;
  arg.fd = -1;
  arg.timeout.tv_sec = -1;
  arg.timeout.tv_nsec = -1;

  do
    rc = uv__io_uring_register(iou->ringfd,
                               UV__IORING_REGISTER_SYNC_CANCEL,
                               &arg,
                               1);
  while (rc == -1 && errno == EINTR);

  /* The original CQE still owns request cleanup and callback delivery. */
  if (rc >= 0)
    return 0;

  err = errno;
  switch (err) {
    case ENOENT:
    case EALREADY:
    case ETIME:
    case EINVAL:
    case ENOSYS:
    case EOPNOTSUPP:
      return UV_EBUSY;
    default:
      return UV__ERR(err);
  }
}

/* In uv__iou_get_sqe(), immediately before its successful return: */
