static void restart_context_poll_cb(uv_fs_poll_t* handle,
                                    int status,
                                    const uv_stat_t* previous,
                                    const uv_stat_t* current) {
  int* restart;

  (void) previous;
  (void) current;
  restart = handle->data;

  ASSERT(*restart == 1);
  ASSERT(status < 0);
  *restart = 0;

  ASSERT(0 == uv_fs_poll_stop(handle));
