  for (i = 0; i < 2; i++) {
    restart = i;
    ASSERT(0 == uv_fs_poll_init(loop, &handle));
    handle.data = &restart;
    ASSERT(0 == uv_timer_init(loop, &timer));
    timer.data = &handle;

    /* An empty path produces an asynchronous stat error. */
    ASSERT(0 == uv_fs_poll_start(&handle,
                                 restart_context_poll_cb,
                                 "",
                                 1));

    if (i == 0) {
      /* Restart while the old context still has a stat request pending. */
      ASSERT(0 == uv_fs_poll_stop(&handle));
      ASSERT(0 == uv_fs_poll_start(&handle,
                                   restart_context_poll_cb,
                                   ".",
                                   1));
    }

    /* On the second pass, restart from inside the error callback instead. */
    ASSERT(0 == uv_timer_start(&timer, restart_context_timer_cb, 100, 0));
    ASSERT(0 == uv_run(loop, UV_RUN_DEFAULT));
    ASSERT(restart == 0);
  }

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

