static uv_fs_poll_t restart_handle;
static int restart_poll_count;
static int restart_close_count;


static void restart_close_cb(uv_handle_t* handle) {
  ASSERT(handle == (uv_handle_t*) &restart_handle);
  restart_close_count++;
}


static void stopped_poll_cb(uv_fs_poll_t* handle,
                            int status,
                            const uv_stat_t* previous,
                            const uv_stat_t* current) {
  (void) handle;
  (void) status;
  (void) previous;
  (void) current;
  ASSERT(0 && "Stopped polling context invoked its callback");
}


static void restart_poll_cb(uv_fs_poll_t* handle,
                            int status,
                            const uv_stat_t* previous,
                            const uv_stat_t* current) {
  (void) previous;
  (void) current;
  ASSERT(handle == &restart_handle);
  ASSERT_EQ(UV_ENOENT, status);
  restart_poll_count++;

  ASSERT_EQ(0, uv_fs_poll_stop(handle));

  if (restart_poll_count == 1) {
    /* The old callback must not reschedule its context after this restart. */
    ASSERT_EQ(0, uv_fs_poll_start(handle,
                                  restart_poll_cb,
                                  "fs_poll_restart_does_not_exist",
                                  1));
    return;
  }

  ASSERT_EQ(2, restart_poll_count);
  uv_close((uv_handle_t*) handle, restart_close_cb);
}


