  uv_loop_t* loop;

  loop = uv_default_loop();
  restart_poll_count = 0;
  restart_close_count = 0;

  ASSERT_EQ(0, uv_fs_poll_init(loop, &restart_handle));
  ASSERT_EQ(0, uv_fs_poll_start(&restart_handle,
                                stopped_poll_cb,
                                "fs_poll_restart_does_not_exist",
                                1));
  /* Leave the first stat request pending when starting the next context. */
  ASSERT_EQ(0, uv_fs_poll_stop(&restart_handle));
  ASSERT_EQ(0, uv_fs_poll_start(&restart_handle,
                                restart_poll_cb,
                                "fs_poll_restart_does_not_exist",
                                1));

  ASSERT_EQ(0, uv_run(loop, UV_RUN_DEFAULT));
  ASSERT_EQ(2, restart_poll_count);
  ASSERT_EQ(1, restart_close_count);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

